-- Node: arb-anticoag-verdict (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Anticoagulated / Coagulopathic — Reverse + Treat","body":"Open [Anticoagulation Reversal](#/tree/anticoag-reversal) (inherited factor deficiency → [Hemophilia](#/tree/hemophilia)).\n\n**Match reversal to the agent:**\n- **Warfarin** — **4-factor PCC** (weight/INR-dosed) + IV vitamin K 10 mg; FFP only if PCC unavailable.\n- **Dabigatran** — **idarucizumab**.\n- **Apixaban / rivaroxaban** — **4-factor PCC** (andexanet alfa is no longer marketed in the US; where available outside the US only).\n- **Antiplatelet** — platelet transfusion is generally NOT beneficial for GI bleed (contrast with intracranial); hold the agent.\n- **Liver disease** — vitamin K, correct fibrinogen (cryoprecipitate), targeted product; the INR overestimates bleeding risk.\n- **Hemophilia / VWD** — factor VIII/IX concentrate or desmopressin/VWF per type; hematology now.\n\nResuscitate in parallel (type and cross, restrictive transfusion) and address the anatomic source once corrected.","citation":[3,5,15],"recommendation":"Agent-specific reversal: PCC+vit K (warfarin), idarucizumab (dabigatran), 4-factor PCC (Xa), factor replacement (hemophilia). Then treat the source.","confidence":"definitive","safetyLevel":"warning"}'::jsonb
WHERE id = 'arb-anticoag-verdict' AND tree_id = 'anorectal-bleeding-hub';

-- Node: acr-xa-critical (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Factor Xa Inhibitor Reversal","body":"**Apixaban (Eliquis), Rivaroxaban (Xarelto), Edoxaban (Savaysa), Fondaparinux (Arixtra)**\n\n**[1] [4-Factor PCC (Kcentra)](#/drug/pcc-4factor/doac reversal)** — first-line in the US, where andexanet alfa is no longer marketed [21]\n• CNS bleeding: 50 units/kg (max 5,000 units) [5,6]\n• Non-CNS: 25 units/kg (max 2,500) or **fixed 2,000 units** (simplest, best evidence) [5]\n• ⚠️ PCC will NOT change the anti-Xa level (anti-Xa measures DOAC in the body, not clotting factor levels)\n\n**[2] [Andexanet alfa (Andexxa)](#/drug/andexanet/doac reversal) — NO LONGER MARKETED IN THE US** (US sales ended 12/22/2025 [21]). Where available outside the US: specific Xa antidote, AHA/ASA Class I for ICH [1]\n• **Low dose** (rivaroxaban ≤10 mg or apixaban ≤5 mg, OR last dose ≥8h ago): 400 mg IV bolus + 4 mg/min × 120 min\n• **High dose** (rivaroxaban >10 mg, apixaban >5 mg, OR unknown dose within 8h): 800 mg IV bolus + 8 mg/min × 120 min\n• ANNEXA-I (NEJM 2024, n=530): superior hemostatic efficacy vs usual care (mostly PCC) in Xa-associated ICH, stopped early [17]\n• ⚠️ **Thrombotic events 10.3% vs 5.6%** (ischemic stroke 6.5% vs 1.5%) with andexanet vs usual care; no mortality benefit (30-day death 27.8% vs 25.5%) [17]\n• ⚠️ NOT shown superior outside ICH; cost ~$25,000+ per dose vs ~$5,000 for PCC\n• Practical: in the US, use 4-factor PCC; andexanet is not available here. Where andexanet is available outside the US, reserve it for ICH with no acute thrombotic contraindication\n\n**[3] If ingested <2h:** [Activated Charcoal](#/drug/activated-charcoal/doac decontamination) 50 g\n\n**[4] If INR elevated:** [Vitamin K](#/drug/vitamin-k/warfarin reversal) 10 mg IV — exclude concurrent vitamin K deficiency\n\n**NOT dialyzable:** Apixaban/Eliquis (~90% protein bound), Rivaroxaban/Xarelto (~95%). Edoxaban/Savaysa (~50% bound) is somewhat dialyzable.\n\n**Monitoring:**\n• Normal INR argues against significant Xa inhibitor level but doesn''t exclude it [4]\n• Anti-Xa level correlates well with drug level; normal anti-Xa excludes clinically relevant Xa inhibitors\n• ⚠️ Anti-Xa assays are **unreliable after andexanet** (drug interferes with assay) — do not use to gauge reversal [17]\n• Follow INR after PCC, then q6h (rebounding INR may indicate waning PCC effect) [5]","citation":[1,3,4,5,6,17,21],"treatment":{"firstLine":{"drug":"4-Factor PCC (Kcentra)","dose":"CNS bleeding: 50 units/kg (max 5,000 units) | Non-CNS: 25 units/kg (max 2,500) or fixed 2,000 units","route":"IV","frequency":"Once","duration":"Single dose","notes":"First-line in the US: andexanet alfa is no longer marketed in the US (US sales ended 12/22/2025). PCC will NOT change anti-Xa level."},"alternative":{"drug":"Andexanet alfa (Andexxa) — NOT marketed in the US","dose":"Low dose: 400 mg IV bolus + 4 mg/min × 120 min | High dose: 800 mg IV bolus + 8 mg/min × 120 min (see body for dose criteria). Historical reference only.","route":"IV","frequency":"Once","duration":"~2 hours","notes":"US sales ended 12/22/2025. Where available outside the US only: AHA/ASA Class I for ICH if available. ANNEXA-I 2024: superior hemostasis vs usual care, no mortality benefit, higher thrombotic risk (10.3% vs 5.6%; ischemic stroke 6.5% vs 1.5%). Reserve for Xa-ICH with no acute thrombotic contraindication."},"monitoring":"INR after PCC, then q6h. Anti-Xa level if available — but UNRELIABLE after andexanet (assay interference). Rebounding INR may indicate waning PCC effect."}}'::jsonb
WHERE id = 'acr-xa-critical' AND tree_id = 'anticoag-reversal';

