-- Node: ards-rescue-check (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Refractory Hypoxemia: ECMO Gate","body":"[ECMO](#/tree/ecmo) | [P/F Berlin calculator](#/calculator/ards-pf-berlin)\n\n**Only after protective ventilation, prone (if eligible), and conservative fluids have been tried.**\n\n**EOLIA trial enrollment criteria, despite optimal ventilation (any one):** [13]\n- P/F below 50 for more than 3 h\n- P/F below 80 for more than 6 h\n- pH below 7.25 with PaCO2 ≥60 mmHg for more than 6 h\n\nThese are the trial''s enrollment gates, not a complete list of referral indications.\n\n**ECMO referral trigger (commonly used, P/F below 80): see the [ECMO consult](#/tree/ecmo).** The ECMO consult sets out the same two statements side by side, with sources: the EOLIA trial enrollment criteria above, and the referral trigger. They are not the same rule.\n\n**Trial caveat:** EOLIA did not significantly reduce 60-day mortality against conventional management (35% vs 46%, P=0.09), and it stopped for futility. ECMO is a referral decision, not a proven survival step.","citation":[13],"options":[{"label":"Meets EOLIA-type gates","description":"Refer for ECMO evaluation now","next":"ards-ecmo-referral","urgency":"critical"},{"label":"Does not meet gates yet","description":"Continue ICU ventilation and reassess","next":"ards-icu","urgency":"urgent"}],"calculatorLinks":[{"id":"ards-pf-berlin","label":"P/F Berlin"}],"summary":"Refractory hypoxemia meeting EOLIA-type gates goes to ECMO evaluation.","safetyLevel":"critical"}'::jsonb
WHERE id = 'ards-rescue-check' AND tree_id = 'ards';

-- Node: ards-ecmo-referral (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Refer for ECMO Evaluation","body":"**Call the ECMO center early when P/F is below 80 despite optimal medical management, including a prone trial** (ELSO 2021 referral trigger). [15] The EOLIA trial enrollment criteria are listed in the ECMO consult.\n\n**ECMO referral trigger (commonly used, P/F below 80): see the [ECMO consult](#/tree/ecmo).** That consult sets out the EOLIA trial criteria and the referral trigger side by side, with sources.\n\n**Have ready before the call:**\n- Ventilator settings: PEEP, FiO2, plateau pressure, driving pressure, and the ABG time\n- Prone sessions completed and their timing\n- Fluid balance and vasopressor dose\n- Contraindications and goals of care\n\n**Trial caveat:** EOLIA showed a non-significant mortality difference (35% vs 46%, P=0.09). Referral buys expert assessment, not a guaranteed survival gain.","citation":[13,15],"recommendation":"Refer for ECMO evaluation when P/F is below 80 despite optimal medical management including a prone trial (ELSO 2021). The ECMO consult shows this referral trigger and the EOLIA enrollment criteria side by side. The trial did not show a significant mortality benefit, so the referral rests on the individual patient.","confidence":"consider","summary":"Early referral for assessment; the trial did not prove a mortality benefit.","safetyLevel":"critical"}'::jsonb
WHERE id = 'ards-ecmo-referral' AND tree_id = 'ards';

