-- Node: gib-exc-anticoag (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Anticoag/Antiplatelet + GI Bleed","body":"Open [Anticoagulation Reversal](#/tree/anticoag-reversal) consult in parallel with source workup. Reversal is independent of source identification — bleeding patient + therapeutic anticoagulant = reverse.\n\n**Identify the agent first** — reversal differs by class:\n\n- **Warfarin** → 4-factor PCC (Kcentra) by INR/weight + vitamin K 10 mg IV\n- **Dabigatran** → idarucizumab (Praxbind) 5 g IV\n- **Apixaban / rivaroxaban** → 4-factor PCC 50 U/kg (andexanet alfa is no longer marketed in the US; off-label, often used due to cost/availability)\n- **Edoxaban** → 4-factor PCC 50 U/kg\n- **DAPT (ASA + P2Y12)** → platelet transfusion is controversial (PATCH trial: harm in ICH; less data in GI bleed). DDAVP can be considered for ASA-induced platelet dysfunction in life-threatening bleeding.\n- **Heparin/LMWH** → protamine (full reversal for UFH; partial for LMWH)\n\n**Restart timing:** balance ongoing bleed risk vs thrombotic risk (mechanical valve, recent VTE, AF + high CHA₂DS₂-VASc). GI bleed alone is rarely sufficient to permanently discontinue — restart in 1-7 days post hemostasis depending on indication.\n\n**Parallel:** transfuse to Hgb 7 (8 in cardiac), platelets >50k for active bleed, fibrinogen >150 for ongoing hemorrhage.","citation":[7,8,9,20],"summary":"Open [Anticoag Reversal](#/tree/anticoag-reversal) — reverse the agent, then work the source. Reversal is independent.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-exc-anticoag' AND tree_id = 'gi-bleed-hub';

-- Node: hmp-exc-coag (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Coagulopathy / Anticoagulant Amplifier","body":"Anticoagulants, antiplatelets, and coagulopathy do not usually CAUSE hemoptysis alone — but they turn a small lesion into a dangerous bleed. Find the underlying source AND correct the coagulopathy if bleeding is significant. [1]\n\n**Next 5 minutes:**\n- Send CBC, PT/INR, aPTT, fibrinogen, type and screen; renal/hepatic function.\n- **If bleeding is life-threatening, reverse:** open [Anticoagulation Reversal](#/tree/anticoag-reversal). Warfarin → 4-factor PCC + vitamin K; DOAC → 4-factor PCC (Xa inhibitors; andexanet alfa is no longer marketed in the US) or idarucizumab (dabigatran); heparin → protamine. Platelets for antiplatelet-associated bleeding or thrombocytopenia. FFP/cryoprecipitate for factor/fibrinogen deficits. [8]\n- **Andexanet is not a free lunch.** ANNEXA-I (NEJM 2024) improved hemostatic efficacy (67.0% vs 53.1%) but nearly **doubled thrombotic events (10.3% vs 5.6%, p=0.048), with ischemic stroke 6.5% vs 1.5%.** Where it is still available outside the US, reserve it for genuinely life-threatening bleeding, and be explicit about the trade with the admitting team. 4F-PCC remains a reasonable alternative where andexanet is unavailable or the thrombotic risk is prohibitive. [15]\n- **Tranexamic acid** is a reasonable adjunct for pulmonary hemorrhage: **nebulized 500-1000 mg (commonly 500 mg in 5 mL) up to q8h**, or **IV 1 g over 10 min**. The evidence base is non-massive hemoptysis. [9,12]\n- Do NOT reverse reflexively for minor blood-streaking — weigh thrombotic risk (mechanical valve, recent VTE/PE, stent). Reverse when the bleed is life-threatening.\n- Still pursue the source: imaging, bronchoscopy, malignancy/TB/infection workup — the amplifier is not the diagnosis.\n\n🛑 Reversal is for LIFE-THREATENING bleeding, not blood-tinged sputum. 🛑 An anticoagulated patient with hemoptysis still needs a source workup — do not stop at “it’s the blood thinner.” 🛑 Reversing a patient with a mechanical valve or a fresh PE trades one lethal problem for another — make that call deliberately, not reflexively.","citation":[1,8,9,12,15],"recommendation":"Send coags + type/screen. Reverse (PCC/vitamin K, idarucizumab, protamine, platelets) ONLY for life-threatening bleeding; TXA adjunct (neb 500-1000 mg q8h or IV 1 g). Weigh thrombotic risk — andexanet roughly doubles thrombotic events. Still work the source.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'hmp-exc-coag' AND tree_id = 'hemoptysis-hub';

-- Node: ich-anticoag (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Anticoagulation Status","body":"**Determine anticoagulant/antiplatelet status immediately.**\n\nDo NOT wait for lab results before initiating reversal — empiric reversal should begin as soon as the agent is identified.\n\n[Causes of ICH](#/info/ich-causes) — hypertensive, CAA, vascular malformation, coagulopathy","citation":[1,2],"options":[{"label":"Warfarin","description":"INR likely elevated — urgent PCC + Vitamin K","next":"ich-warfarin-rev","urgency":"critical"},{"label":"Dabigatran (Pradaxa)","description":"Direct thrombin inhibitor — idarucizumab reversal","next":"ich-dabi-rev","urgency":"critical"},{"label":"Xa Inhibitor (apixaban, rivaroxaban, edoxaban)","description":"Factor Xa inhibitor — 4-factor PCC (andexanet alfa no longer marketed in the US)","next":"ich-xa-rev","urgency":"critical"},{"label":"Heparin / LMWH","description":"Protamine sulfate reversal","next":"ich-heparin-rev","urgency":"urgent"},{"label":"Not on anticoagulation","description":"Antiplatelet only or no antithrombotics","next":"ich-coag-adj"}],"summary":"Determine anticoagulant type: warfarin, dabigatran, Xa inhibitor, heparin, or antiplatelet","safetyLevel":"critical"}'::jsonb
WHERE id = 'ich-anticoag' AND tree_id = 'ich';

-- Node: ich-xa-rev (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Xa Inhibitor Reversal","body":"**Applies to: apixaban, rivaroxaban, edoxaban**\n\n**Option 1 (first-line in the US): [4-Factor PCC](#/drug/pcc-4factor/doac ich)**\n• 50 IU/kg IV\n• Available in the US; andexanet alfa is no longer marketed here\n• Onset: 15–30 minutes\n\n**Option 2: Andexanet alfa (Andexxa) — NO LONGER MARKETED IN THE US** (US sales ended 12/22/2025)\n• Where available outside the US: specific Xa inhibitor reversal agent\n• Dosing depends on agent and time since last dose\n• Not an option for US patients — use 4-factor PCC\n\n**If last dose within 2h (intubated patient):**\n• Activated charcoal 50 g via OG/NG tube\n\n**Monitoring:**\n• Anti-Xa levels if available (not required before treatment)\n• Repeat CT at 6h to assess for expansion\n• Watch for thrombotic complications post-reversal\n\n**Basis for the 50 IU/kg PCC dose:** Neurocritical Care Society / SCCM antithrombotic reversal guideline [5], AHA/ASA 2022 [1], ESO/EANS 2025 [2], and the 2020 ACC bleeding decision pathway [4].\n\n**Basis for the andexanet availability note (harm signal):** ANNEXA-4 (n=352, single-arm) reported excellent/good hemostasis in 82% at 12h [19]. The randomized ANNEXA-I trial (n=530, Xa-inhibitor-associated ICH) showed better hematoma-expansion control than usual care but more thrombotic events — ≥1 thrombotic event 10.3% vs 5.6%, ischemic stroke 6.5% vs 1.5%, MI 4.2% vs 1.5% [20]. FDA concluded from post-marketing data that risks outweighed benefits (30-day thrombosis 14.6% vs 6.9%; thrombosis-related death 2.5% vs 0.9%), and andexanet alfa ceased US commercial availability on 22 Dec 2025; it remains available in the EU, UK, and Japan (Ondexxya) [21].","citation":[1,2,4,5,19,20,21],"next":"ich-bp","treatment":{"firstLine":{"drug":"4-Factor PCC","dose":"50 IU/kg","route":"IV","frequency":"Once","duration":"Single dose","notes":"Most widely available. Onset 15-30 min. Consider activated charcoal 50 g via OG/NG if last dose within 2h (intubated only)."},"alternative":{"drug":"Andexanet alfa (Andexxa) — NOT marketed in the US","dose":"Varies by agent and time since last dose (historical reference)","route":"IV","frequency":"Bolus then infusion","duration":"Per protocol","notes":"US sales ended 12/22/2025. Where available outside the US only. Watch for thrombotic complications."},"monitoring":"Anti-Xa levels if available (not required before treatment). Repeat CT at 6h. Monitor for thrombotic complications post-reversal."},"summary":"4-factor PCC 50 IU/kg for Xa inhibitor reversal — andexanet alfa is no longer marketed in the US","safetyLevel":"critical"}'::jsonb
WHERE id = 'ich-xa-rev' AND tree_id = 'ich';

-- Node: hemo-doac-reversal (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"DOAC Reversal","body":"**Direct thrombin inhibitor (Dabigatran):**\n• [Idarucizumab](#/drug/idarucizumab/hemoptysis) (Praxbind) 5g IV\n\n**Factor Xa inhibitors (rivaroxaban, apixaban, edoxaban):**\n• [4-Factor PCC](#/drug/kcentra/hemoptysis) 50 units/kg [1] (first-line in the US)\n• Andexanet alfa is no longer marketed in the US (where available outside the US only)","citation":[1],"recommendation":"Reverse dabigatran with idarucizumab. For Xa inhibitors, use 4F-PCC (andexanet alfa is no longer marketed in the US).","treatment":{"firstLine":{"drug":"Idarucizumab (dabigatran)","dose":"5g IV (two 2.5g vials)","route":"IV","frequency":"Once","duration":"Single dose","notes":"Specific for dabigatran only"},"alternative":{"drug":"4-Factor PCC (Xa inhibitors)","dose":"50 units/kg IV","route":"IV","frequency":"Once","duration":"Single dose","notes":"For rivaroxaban, apixaban, edoxaban (andexanet alfa no longer marketed in the US)"},"monitoring":"Clinical bleeding assessment. Standard coags do not reflect DOAC reversal."},"confidence":"recommended"}'::jsonb
WHERE id = 'hemo-doac-reversal' AND tree_id = 'massive-hemoptysis';

-- Node: rhabdo-drug-induced (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Drug/Toxin-Induced Rhabdomyolysis","body":"**Statin-induced:**\n• Risk ~0.1% overall, higher with:\n  - High-intensity statins (rosuvastatin, atorvastatin high-dose)\n  - Fibrate combination (avoid gemfibrozil)\n  - CYP3A4 inhibitors (cyclosporine, macrolides, azoles)\n• **Management:** STOP statin immediately. Can rechallenge with different statin after recovery if needed.\n\n**Cocaine/Amphetamines:**\n• Sympathomimetic excess + hyperthermia + vasoconstriction\n• Treat hyperthermia aggressively\n• Avoid pure beta-blockers (unopposed alpha); mixed alpha/beta agents (labetalol, carvedilol): evidence conflicts, not first line\n\n**Alcohol:**\n• Direct myotoxicity + immobilization + electrolyte derangement\n• Check and correct Mg, K, Phos\n\n**NMS/Serotonin Syndrome:**\n• See [Serotonin Syndrome](#/tree/serotonin-syndrome) consult\n• Cooling, benzodiazepines, supportive care\n• Cyproheptadine for serotonin syndrome\n• Dantrolene for NMS with severe rigidity","citation":[1,4],"next":"rhabdo-workup","summary":"Statin-induced: stop immediately (rechallenge later OK), cocaine: treat hyperthermia/avoid beta-blockers, NMS/SS: see specific consults","skippable":true}'::jsonb
WHERE id = 'rhabdo-drug-induced' AND tree_id = 'rhabdomyolysis';

-- Node: stemi-special (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Special Populations","body":"**Women:**\n• Less likely to present with central chest pain [28]\n• Same risk factors and treatment as men\n• CV mortality has remained higher in women since 1980s\n\n**Elderly (>75 years):**\n• More atypical presentations (dyspnea, syncope, nausea)\n• Higher complication rate, more contraindications to reperfusion\n• Age alone is NOT a reason to withhold reperfusion [29]\n• Consider half-dose tenecteplase if fibrinolysis indicated\n\n**Cocaine-associated STEMI:**\n• PCI strongly preferred over fibrinolysis (higher ICH risk with lytics)\n• Benzodiazepines for chest pain, HR, and BP control\n• **Avoid pure beta-blockers** (propranolol, metoprolol, esmolol; unopposed alpha stimulation). Mixed alpha/beta agents such as [Labetalol](#/drug/labetalol/acs) and carvedilol: evidence conflicts, not first line [30]\n\n**Post-cardiac arrest with STEMI:**\n• Early cath for sustained ROSC with STEMI or new LBBB\n• 2–3× higher favorable survival with early cath lab access [31]\n• Consider ECMO for refractory VF/pVT","citation":[28,29,30,31],"next":"stemi-dispo","summary":"Women: more atypical presentations; elderly: half-dose lytics; cocaine: avoid pure beta-blockers, PCI preferred","skippable":true}'::jsonb
WHERE id = 'stemi-special' AND tree_id = 'stemi';

